<script type="module">
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

const W = 240, H = 242, unit = 0.01965;
const pitch = 0.349, sin = Math.sin(pitch), cos = Math.cos(pitch);
const V = (x,y,z) => new THREE.Vector3(x,y,z);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xb5a79a);

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true, antialias: true });
