function at(x,y,z) {
  return V((x-W/2)*unit,1.8+((H/2-y)*unit+sin*z)/cos,z);
}
function onPlane(x,y,height) {
  return V((x-W/2)*unit,height,((height-1.8)*cos-(H/2-y)*unit)/sin);
}
function group(name,parent,p=V(0,0,0)) {
  const g = new THREE.Group();
  g.name = name;
  g.position.copy(p);
  parent.add(g);
  return g;
}
function mat(color, props={}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.85, ...props });
}
function add(parent,name,geo,material,p=V(0,0,0),shadow=true) {
  const mesh = new THREE.Mesh(geo,material);
  mesh.name = name;
  mesh.position.copy(p);
  mesh.castShadow = shadow;
  mesh.receiveShadow = shadow;
  parent.add(mesh);
  return mesh;
}
const sphere = new THREE.SphereGeometry(1,32,24);
function oval(parent,name,p,scale,material,shadow=true) {
  const m = add(parent,name,sphere,material,p,shadow);
