function profile(rows,y) {
  const i=Math.min(rows.length-2,Math.max(0,rows.findIndex(r=>r[0]>=y)-1));
  const a=rows[i],b=rows[i+1],before=rows[Math.max(i-1,0)],after=rows[Math.min(i+2,rows.length-1)];
  const h=b[0]-a[0], t=THREE.MathUtils.clamp((y-a[0])/h,0,1), t2=t*t,t3=t2*t;
  return a.slice(1).map((unused,k)=>{
    const j=k+1;
    const m0=(b[j]-before[j])/(b[0]-before[0]),m1=(after[j]-a[j])/(after[0]-a[0]);
    return (2*t3-3*t2+1)*a[j]+(t3-2*t2+t)*m0*h+(-2*t3+3*t2)*b[j]+(t3-t2)*m1*h;
  });
}
function smooth(a,b,x) {
  return THREE.MathUtils.smoothstep(x,a,b);
}
function makeCharacter(name,rows,cut,isRight) {
  const pivot=V(rows[3][1],.46,rows[3][2]);
  const root=group(name,scene,pivot);
  const torso=group('torso',root);
  const headOrigin=V(rows[7][1],cut,rows[7][2]);
  const head=group('head',root,headOrigin.clone().sub(pivot));
  const eyes=group('eyes',head), mouth=group('mouth',head);
  const coat = new THREE.Color(isRight?0xf5b529:0xf1ae25);
  const gold = new THREE.Color(isRight?0xe99915:0xe89a17);
  const cream = new THREE.Color(isRight?0xe6c38a:0xe1c18a);
  function surface(y,a) {
    const [x,z,rx,rz]=profile(rows,y);
    const muzzle=isRight
      ? .062*Math.exp(-((y-2.57)**2)/.044-((a+.91)**2)/.35)
      : .042*Math.exp(-((y-2.31)**2)/.044-((a-.32)**2)/.28);
    return V(x+(rx+muzzle)*Math.sin(a),y,z+(rz+muzzle)*Math.cos(a));
  }
  function normal(y,a) {
    const dy=surface(y+.002,a).sub(surface(y-.002,a));
    const da=surface(y,a+.003).sub(surface(y,a-.003));
    return da.cross(dy).normalize();
  }
  function skin(container,origin,min,max) {
    const theta=v=>(1-v*2)*Math.PI;
    const yAt=u=>THREE.MathUtils.lerp(min,max,u);
    const geo=meshGrid(54,100,(u,v)=>{
      const y=yAt(u),a=theta(v);
      const p=surface(y,a).sub(origin);
      const frontAngle=isRight?-.33:.07;
      const patch=Math.sqrt(((y-(isRight?.80:.86))/(isRight?.81:.83))**2+
        ((a-frontAngle)/(isRight?1.12:.96))**2);
      const mottling=Math.sin(43*y+17*a)*Math.sin(29*y-31*a)*.012+
        Math.sin(19*y+15*a)*.009+Math.sin(8*y+6*a)*.016;
      const frontShade=.18+.17*Math.cos(a+.5)*Math.exp(-((y-2.20)**2)/.38);
      const c=coat.clone().lerp(gold,frontShade).lerp(cream,1-smooth(.92,1.04,patch+mottling*1.1));
      c.multiplyScalar(1+mottling);
      p.color=c;
      return p;
    },true,(u,v)=>normal(yAt(u),theta(v)));
    add(container,container===head?'head-volume':'body-volume',geo,fabric);
  }
  skin(torso,pivot,rows[0][0],cut);
  skin(head,headOrigin,cut,rows.at(-1)[0]);
  return {root,head,eyes,mouth,pivot,headOrigin,surface,normal};
}

