  g.quaternion.setFromUnitVectors(V(0,0,1),outward);
  oval(g,'ochre-eyelid',V(0,0,-.012),[w*1.14,h*1.10,.068],eyeRim);
  oval(g,'dark-olive-eye',V(0,0,.013),[w,h,.081],iris);
  oval(g,'pupil',V(w*lookX,h*lookY,.074),[w*.64,h*.70,.028],pupil,false);
  oval(g,'soft-eye-highlight',V(w*(lookX-.35),h*(lookY+.47),.098),[w*.105,h*.093,.008],glint,false);
}
