function arm(c,name,coords,radii,color=armGold,flatten=1) {
  const points=coords.map(p=>at(...p));
  const origin=points[0];
  const g=group(name,c.root,origin.clone().sub(c.pivot));
  sweep(g,'upper-and-lower-arm',points.map(p=>p.sub(origin.clone())),radii,color,flatten);
  return {g,origin};
}
function hand(armPart,name,anchor,palms,digits,material) {
  const origin=at(...anchor);
  const h=group(name,armPart.g,origin.clone().sub(armPart.origin));
  for(const [label,p,s,rz] of palms) {
    const m=oval(h,label,at(...p).sub(origin),s,material);
    m.rotation.z=rz;
  }
  for(const [label,points,radii] of digits) {
    sweep(h,label,points.map(p=>at(...p).sub(origin)),radii,material,1);
  }
  return h;
